def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    count = 2

    if count == 0:
        return None

    average_total_revenue = (v1 + v2) / count

    return {
        "value": average_total_revenue,
        "trace": {
            "v1": v1,
            "v2": v2,
            "count": count,
            "average_total_revenue": average_total_revenue,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
